insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.generic.reasons[0].cites[0].quote', 'Allah ngendika: Saben amale anak Adam iku kanggo dheweke, kajaba pasa; satemene iku kanggo Ingsun, lan Ingsun bakal menehi ganjaran.');
