insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.obligatory.reasons[0].cites[1].quote', 'Sapa sing pasa Ramadan kanthi iman lan ngarep-arep ganjaran, dosa-dosane sing wis kepungkur bakal diampuni.');
