insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.obligatory.reasons[0].cites[1].references[1].hadith', '760');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.obligatory.reasons[0].cites[1].references[0].collection', 'bukhari');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.obligatory.reasons[0].cites[1].references[0].hadith', '38');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.obligatory.reasons[0].cites[0].quote', 'Islam iku dibangun ing lima perkara: syahadat yen ora ana sesembahan kang bener kajaba Allah lan yen Muhammad iku utusan Allah, nindakake shalat, mbayar zakat, nindakake haji, lan pasa Ramadan.');
