insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].intro', 'Diriwayatake dening Abu Ubaid (ra.)');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].quote', 'Aku melu shalat Id bebarengan karo Umar (ra.). Dheweke nindakake shalat sadurunge khutbah, banjur ngendika: Rasulullah shallallahu alaihi wasallam nglarang pasa ing rong dina iki. Ing dina Idul Adha, panjenengan mangan daging kurban panjenengan; lan ing dina Idul Fitri, panjenengan mungkasi pasa panjenengan.');
