insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.prohibiting.reasons[0].cites[0].intro', 'Diriwayatake dening Abu Hurairah (ra.)');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.prohibiting.reasons[0].cites[0].quote', 'Rasulullah shallallahu alaihi wasallam nglarang pasa ing rong dina: dina Idul Fitri lan dina Idul Adha.');
