insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[1].cites[0].intro', 'Abu Qatadah (ra.) ngriwayatake yen Rasulullah shallallahu alaihi wasallam ngendika:');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[1].cites[0].quote', 'Aku ngarep-arep marang Allah supaya pasa ing dina Arafah nglebur dosa-dosa setaun sadurunge lan setaun sawise, lan aku ngarep-arep marang Allah supaya pasa ing dina Asyura nglebur dosa-dosa setaun sadurunge.');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[1].cites[0].references[0].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[1].cites[0].references[0].hadith', '1162');
