insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[1].headlines.ashura', 'Dina Asyura');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[1].id', 'fasting-reason-arafah-or-ashura');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[1].title', 'Dina Arafah lan Asyura');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[2].cites[0].intro', 'Salah sawijining garwa Rasulullah shallallahu alaihi wasallam (radhiyallahu anha) ngendika:');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[2].cites[0].quote', 'Rasulullah shallallahu alaihi wasallam biyasa pasa ing sanga dina wiwitan sasi Dzulhijah, dina Asyura, lan telung dina saben sasi.');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[1].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[1].hadith', '2417');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[0].collection', 'abudawud');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[0].hadith', '2437');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[2].id', 'fasting-reason-first-9-dhu-al-hijjah');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[2].title', 'Sanga dina wiwitan sasi Dzulhijah');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[1].intro', 'Diriwayatake dening Abdullah bin Amr bin Ash:');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[1].quote', 'Kanggo panjenengan cukup pasa telung dina saben sasi, amarga siji kabecikan diganjar sepuluh tikel, mula iku kaya pasa setaun kebak.');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[1].references[0].collection', 'bukhari');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[1].references[0].hadith', '1975');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[2].intro', 'Abu Qatadah (ra.) ngriwayatake yen Rasulullah shallallahu alaihi wasallam ngendika:');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[2].quote', 'Pasa telung dina saben sasi, lan pasa Ramadan nganti Ramadan sabanjure, iku kaya pasa terus-terusan.');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[2].references[0].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[2].references[0].hadith', '1162');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[3].intro', 'Rasulullah shallallahu alaihi wasallam ngendika marang Abu Dzar:');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[3].quote', 'Sapa sing pasa telung dina saben sasi, iku kaya pasa salawase.');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[3].references[0].collection', 'ibnmajah');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[3].references[0].hadith', '1708');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[4].intro', 'Diriwayatake saka Jarir bin Abdullah yen Nabi shallallahu alaihi wasallam ngendika:');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[4].quote', 'Pasa telung dina saben sasi iku kaya pasa salawase, lan dina-dina putih (Ayyam al-Bidh) yaiku dina kaping telulas, patbelas, lan limolas.');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[4].references[0].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[4].references[0].hadith', '2420');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[5].intro', 'Diriwayatake dening Abu Hurairah (ra.):');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[5].quote', 'Kinasihku (Nabi Muhammad shallallahu alaihi wasallam) menehi wasiat marang aku telung perkara: pasa telung dina saben sasi, shalat Dhuha rong rakaat, lan shalat Witir sadurunge turu.');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[5].references[0].collection', 'bukhari');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[5].references[0].hadith', '1981');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[6].intro', 'Abu Darda (ra.) ngriwayatake:');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[6].quote', 'Kinasihku (Nabi Muhammad shallallahu alaihi wasallam) menehi wasiat telung amalan sing ora bakal daklalekake, lan dheweke mewasiatake marang aku supaya pasa telung dina saben sasi.');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[6].references[0].collection', 'abudawud');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[6].references[0].hadith', '1433');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[0].intro', 'Nabi Muhammad shallallahu alaihi wasallam menehi wasiat marang Abu Dzar (ra.):');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[0].quote', 'Yen panjenengan pasa ing sawetara dina saben sasi, banjur pasa ing dina kaping telulas, patbelas, lan limolas.');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[0].references[0].collection', 'tirmidhi');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].cites[0].references[0].hadith', '761');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].id', 'fasting-reason-white-days');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[3].title', 'Dina-dina Putih');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[4].cites[1].intro', 'Usamah bin Zaid (ra.) ngriwayatake yen Rasulullah shallallahu alaihi wasallam ngendika:');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[4].cites[1].quote', 'Iku rong dina nalika amal-amal diaturake marang Rabbul Alamin, lan aku seneng amalku diaturake nalika aku lagi pasa.');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[4].cites[1].references[0].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[4].cites[1].references[0].hadith', '2358');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[4].cites[2].intro', 'Nabi shallallahu alaihi wasallam ditakoni dening Abu Qatadah al-Anshari (ra.) bab pasa ing dina Senin, banjur ngendika:');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[4].cites[2].quote', 'Iku dina nalika aku dilairake, lan ing dina iku aku diutus minangka nabi, utawa wahyu diturunake marang aku.');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[4].cites[2].references[0].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[4].cites[2].references[0].hadith', '1162b');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[4].cites[3].intro', 'Aisyah (ra.) ngriwayatake:');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[4].cites[3].quote', 'Nabi shallallahu alaihi wasallam biyasa ngutamakake pasa ing dina Senin lan Kamis.');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[4].cites[3].references[0].collection', 'tirmidhi');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[4].cites[3].references[0].hadith', '745');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[4].cites[0].intro', 'Kandhaan iki diriwayatake dening Abu Hurairah (ra.):');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[4].cites[0].quote', 'Amal-amal diaturake ing dina Senin lan Kamis, lan aku seneng amalku diaturake nalika aku lagi pasa.');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[4].cites[0].references[1].collection', 'riyadussalihin');
insert into i18n_bundles (locale, code, value) values ('jv', 'fasting.reason-groups.voluntary.reasons[4].cites[0].references[1].hadith', '1256');
